code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 2):
                centers.append((r, c))
    # Each hollow diamond has four tips. Join matching tip orientations when
    # their coordinates lie on a common row or column.
    tips = {}
    for r, c in centers:
        tips[(r-1, c)] = ((r,c), 'v')
        tips[(r+1, c)] = ((r,c), 'v')
        tips[(r, c-1)] = ((r,c), 'h')
        tips[(r, c+1)] = ((r,c), 'h')
    for i, a in enumerate(centers):
        for b in centers[i+1:]:
            candidates=[]
            for p, (owner_p, ori_p) in tips.items():
                if owner_p != a: continue
                for q, (owner_q, ori_q) in tips.items():
                    if owner_q != b or ori_p != ori_q: continue
                    if p[0] == q[0] and p[1] != q[1]:
                        lo, hi=sorted((p[1],q[1]))
                        candidates.append((hi-lo, 'row', p[0], lo, hi))
                    elif p[1] == q[1] and p[0] != q[0]:
                        lo, hi=sorted((p[0],q[0]))
                        candidates.append((hi-lo, 'col', p[1], lo, hi))
            if not candidates: continue
            _, axis, fixed, lo, hi = min(candidates)
            # Only bridge empty cells; an intervening shape blocks a longer link.
            if axis == 'row':
                cells=[(fixed,x) for x in range(lo+1,hi)]
            else:
                cells=[(x,fixed) for x in range(lo+1,hi)]
            if all(grid[r][c] == 0 for r,c in cells):
                for r,c in cells: out[r][c]=1
    return out
